#include "trajectory.h"
#include "math3d.h"
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
static double wrap_interp(float a,float b,double u){double d=fmod((double)b-a+540.0,360.0)-180.0;return a+d*u;}
int load_trajectory(NodePosition *p,const char *path){if(!p||!path)return 0;FILE *f=fopen(path,"r");if(!f){perror(path);return 0;}size_t cap=32;p->trajectory=malloc(cap*sizeof(*p->trajectory));if(!p->trajectory){fclose(f);return 0;}char line[512];while(fgets(line,sizeof(line),f)){double t,lat,lon,h;float yaw,pitch,roll;if(line[0]=='#'||sscanf(line,"%lf,%lf,%lf,%lf,%f,%f,%f",&t,&lat,&lon,&h,&yaw,&pitch,&roll)!=7)continue;if(p->trajectory_count==cap){cap*=2;TrajectoryPoint *q=realloc(p->trajectory,cap*sizeof(*q));if(!q){free(p->trajectory);p->trajectory=NULL;fclose(f);return 0;}p->trajectory=q;}Geodetic geo={lat,lon,h};p->trajectory[p->trajectory_count++]=(TrajectoryPoint){t,geo,(Attitude){yaw,pitch,roll},geodetic_to_ecef(geo)};}fclose(f);if(p->trajectory_count<2)return 0;for(size_t i=1;i<p->trajectory_count;i++)if(p->trajectory[i].t<=p->trajectory[i-1].t)return 0;return 1;}
int update_state(Node *n,NodePosition *p,double t){if(!n||!p||p->trajectory_count<2)return 0;size_t i=0;if(t>=p->trajectory[p->trajectory_count-1].t)i=p->trajectory_count-2;else while(i+1<p->trajectory_count-1&&p->trajectory[i+1].t<t)i++;TrajectoryPoint a=p->trajectory[i],b=p->trajectory[i+1];double dt=b.t-a.t;if(dt<=0)return 0;double u=(t-a.t)/dt;if(u<0)u=0;if(u>1)u=1;p->position=add(a.ecef,scale(sub(b.ecef,a.ecef),u));p->velocity=scale(sub(b.ecef,a.ecef),1.0/dt);ecef_to_geodetic(p->position,&p->geodetic);n->velocity=p->velocity;n->attitude=(Attitude){(float)wrap_interp(a.attitude.heading,b.attitude.heading,u),(float)(a.attitude.pitch+(b.attitude.pitch-a.attitude.pitch)*u),(float)wrap_interp(a.attitude.roll,b.attitude.roll,u)};return 1;}
